   - ทำทั้งไฟล์ใน Transaction เดียว: ผิดพลาดจุดไหน ROLLBACK ทั้งหมด
   - นี่คือ "ข้อมูลย้อนหลัง" ที่ผ่านขั้นตอนอนุมัติ/ตัดงบมาแล้ว จึงปิด trigger ระหว่างนำเข้า
