/* ---------------------------------------------------------------------
   3) ตรวจความสอดคล้องก่อน COMMIT (ไม่พึ่ง logic.sql) — ผิดข้อใด ROLLBACK ทั้งหมด
   --------------------------------------------------------------------- */
IF EXISTS (SELECT 1
           FROM dbo.budget_limits AS b
           OUTER APPLY (SELECT SUM(p.total_amount) AS po_total
                        FROM dbo.purchase_orders AS p
                        INNER JOIN dbo.requisitions AS r ON r.requisition_id = p.requisition_id
                        WHERE r.budget_id = b.budget_id
                          AND p.status <> 'Cancelled') AS x
           WHERE b.used_amount <> ISNULL(x.po_total, 0))
    THROW 50901, N'used_amount ไม่ตรงกับยอดใบสั่งซื้อที่ยังไม่ยกเลิก', 1;

IF EXISTS (SELECT 1
           FROM dbo.purchase_orders AS p
           OUTER APPLY (SELECT SUM(pi.line_total) AS items_total
                        FROM dbo.po_items AS pi
                        WHERE pi.po_id = p.po_id) AS x
           WHERE p.subtotal_amount <> ISNULL(x.items_total, 0))
    THROW 50902, N'subtotal_amount ไม่ตรงกับผลรวมรายการในใบสั่งซื้อ', 1;

IF EXISTS (SELECT 1
           FROM dbo.purchase_orders AS p
           CROSS APPLY (SELECT COUNT(*)          AS line_count,
                               SUM(f.done)       AS received_lines,
                               SUM(f.progress)   AS progress_lines,
                               SUM(f.has_any)    AS receipt_lines
                        FROM dbo.po_items AS pi
                        CROSS APPLY (SELECT ISNULL(MAX(CASE WHEN gr.received_status = 'Accepted' THEN 1 ELSE 0 END), 0) AS done,
                                            ISNULL(MAX(CASE WHEN gr.received_status IN ('Accepted', 'Partial') THEN 1 ELSE 0 END), 0) AS progress,
                                            ISNULL(MAX(1), 0) AS has_any
                                     FROM dbo.goods_receipts AS gr
                                     WHERE gr.po_id = pi.po_id
                                       AND gr.line_no = pi.line_no) AS f
                        WHERE pi.po_id = p.po_id) AS s
           WHERE (p.status = 'Cancelled' AND s.receipt_lines > 0)
              OR (p.status <> 'Cancelled'
                  AND p.status <> CASE WHEN s.line_count > 0 AND s.received_lines = s.line_count THEN 'Received'
                                       WHEN s.progress_lines > 0 THEN 'Partially Received'
                                       ELSE 'Issued' END))
    THROW 50903, N'สถานะใบสั่งซื้อไม่ตรงกับข้อมูลการรับสินค้า', 1;

IF EXISTS (SELECT 1
           FROM dbo.goods_receipts AS g
           WHERE g.received_status = 'Accepted'
           GROUP BY g.po_id, g.line_no
           HAVING COUNT(*) > 1)
    THROW 50904, N'รายการเดียวกันถูกตรวจรับครบ (Accepted) มากกว่า 1 ครั้ง', 1;

IF EXISTS (SELECT 1
           FROM dbo.po_items AS pi
           INNER JOIN dbo.purchase_orders AS p ON p.po_id = pi.po_id
           WHERE pi.requisition_id <> p.requisition_id)
    THROW 50905, N'รายการในใบสั่งซื้ออ้างถึงใบขอซื้อคนละใบกับใบสั่งซื้อ (CONVERTED TO)', 1;

ALTER TABLE dbo.purchase_orders ENABLE TRIGGER ALL;
ALTER TABLE dbo.goods_receipts ENABLE TRIGGER ALL;

COMMIT TRANSACTION;

SELECT t.table_name, t.row_count
FROM (VALUES
    ('departments',       (SELECT COUNT(*) FROM dbo.departments)),
    ('staff',             (SELECT COUNT(*) FROM dbo.staff)),
    ('vendors',           (SELECT COUNT(*) FROM dbo.vendors)),
    ('budget_limits',     (SELECT COUNT(*) FROM dbo.budget_limits)),
    ('requisitions',      (SELECT COUNT(*) FROM dbo.requisitions)),
    ('requisition_items', (SELECT COUNT(*) FROM dbo.requisition_items)),
    ('approvals',         (SELECT COUNT(*) FROM dbo.approvals)),
    ('purchase_orders',   (SELECT COUNT(*) FROM dbo.purchase_orders)),
    ('po_items',          (SELECT COUNT(*) FROM dbo.po_items)),
    ('goods_receipts',    (SELECT COUNT(*) FROM dbo.goods_receipts))
) AS t (table_name, row_count);
GO